// 1D Array Base + Offset Addressing
int arr[10];
size_t index = 5;

// Address(arr[i]) = Base + i * sizeof(T)
int *p_start = arr;
int *p_offset = arr + index;

// Pointer arithmetic automatically scales by sizeof(int)
size_t byte_diff = (char*)p_offset - (char*)p_start;
// byte_diff == index * sizeof(int)


// 2D Array Memory Layout (Row-Major)
#define ROWS 4
#define COLS 8
int matrix[ROWS][COLS];

// Linear address calculation for matrix[r][c]
int r = 2, c = 3;
// Offset = (r * COLS) + c
int *base = (int*)matrix;
int element = *(base + (r * COLS) + c);


// Addressability and Alignment
struct {
    char a;  // 1 byte
    int b;   // 4 bytes (often 3 padding bytes follow 'a')
} aligned_struct;

// Starting address of 'b' must be divisible by 4 (typical arch)
size_t addr_a = (size_t)&aligned_struct.a;
size_t addr_b = (size_t)&aligned_struct.b;
// (addr_b % 4) == 0
// addr_b - addr_a >= 4 (due to alignment padding)
